import React from 'react';

const Navbar = ({ username, balance, onLogout, setActiveTab, activeTab }) => {
    const tabs = [
        { id: 'explore', label: 'Explore', icon: '🔍' },
        { id: 'trading', label: 'Trade & Chart', icon: '📈' },
        { id: 'holdings', label: 'Holdings', icon: '💼' },
        { id: 'positions', label: 'Positions', icon: '⚡' },
        { id: 'orders', label: 'Orders', icon: '📋' },
        { id: 'watchlist', label: 'Watchlist', icon: '⭐' },
        { id: 'recharge', label: 'Recharge', icon: '💳' },
    ];

    return (
        <nav style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            padding: '14px 28px',
            background: 'var(--bg-surface)',
            borderBottom: '1px solid var(--border-color)',
            position: 'sticky',
            top: 0,
            zIndex: 100,
            flexWrap: 'wrap',
            gap: '12px',
            boxShadow: 'var(--shadow-soft)'
        }}>
            {/* Soft Brand Logo */}
            <div 
                style={{ display: 'flex', alignItems: 'center', gap: '10px', cursor: 'pointer' }}
                onClick={() => setActiveTab('explore')}
            >
                <div style={{
                    width: '38px',
                    height: '38px',
                    borderRadius: '10px',
                    background: 'linear-gradient(135deg, #38bdf8 0%, #10b981 100%)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    color: '#ffffff',
                    fontWeight: '800',
                    fontSize: '18px',
                    boxShadow: '0 4px 12px rgba(56, 189, 248, 0.3)'
                }}>
                    📈
                </div>
                <div>
                    <h2 style={{ 
                        margin: 0, 
                        fontSize: '18px', 
                        fontWeight: '800', 
                        background: 'linear-gradient(90deg, #38bdf8, #10b981)',
                        WebkitBackgroundClip: 'text',
                        WebkitTextFillColor: 'transparent'
                    }}>
                        DemoTrader
                    </h2>
                    <span style={{ fontSize: '11px', color: 'var(--text-muted)', fontWeight: '600' }}>
                        BSE & NSE LIVE
                    </span>
                </div>
            </div>

            {/* Soft Navigation Pills */}
            <div style={{ 
                display: 'flex', 
                gap: '6px', 
                background: '#111927',
                padding: '5px',
                borderRadius: '12px',
                border: '1px solid var(--border-color)',
                flexWrap: 'wrap'
            }}>
                {tabs.map((tab) => {
                    const isActive = activeTab === tab.id;
                    return (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id)}
                            style={{
                                padding: '7px 14px',
                                background: isActive ? 'var(--bg-surface-hover)' : 'transparent',
                                color: isActive ? 'var(--accent-primary)' : 'var(--text-secondary)',
                                border: isActive ? '1px solid #334666' : '1px solid transparent',
                                borderRadius: '8px',
                                cursor: 'pointer',
                                fontSize: '13px',
                                fontWeight: isActive ? '700' : '500',
                                transition: 'all 0.2s ease',
                                display: 'flex',
                                alignItems: 'center',
                                gap: '6px'
                            }}
                        >
                            <span>{tab.icon}</span>
                            <span>{tab.label}</span>
                        </button>
                    );
                })}
            </div>

            {/* Soft Balance & Profile Widget */}
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                <div style={{
                    background: 'var(--accent-emerald-soft)',
                    border: '1px solid rgba(16, 185, 129, 0.3)',
                    padding: '6px 14px',
                    borderRadius: '20px',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '8px'
                }}>
                    <span style={{ fontSize: '13px' }}>💰 Cash</span>
                    <span style={{ fontWeight: '700', color: 'var(--accent-emerald)', fontSize: '14px' }}>
                        ₹{(balance || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </span>
                </div>

                <div style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '8px',
                    background: '#111927',
                    padding: '5px 12px',
                    borderRadius: '10px',
                    border: '1px solid var(--border-color)'
                }}>
                    <span style={{ fontSize: '13px' }}>👤</span>
                    <span style={{ color: 'var(--text-primary)', fontSize: '13px', fontWeight: '600' }}>
                        {username}
                    </span>
                </div>

                <button
                    onClick={onLogout}
                    style={{
                        padding: '6px 12px',
                        background: 'transparent',
                        color: 'var(--accent-rose)',
                        border: '1px solid rgba(244, 63, 94, 0.4)',
                        borderRadius: '8px',
                        cursor: 'pointer',
                        fontSize: '12px',
                        fontWeight: '600',
                        transition: 'all 0.2s ease'
                    }}
                    onMouseEnter={(e) => e.target.style.background = 'var(--accent-rose-soft)'}
                    onMouseLeave={(e) => e.target.style.background = 'transparent'}
                >
                    Logout
                </button>
            </div>
        </nav>
    );
};

export default Navbar;
